<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/../config/delivery_control.php';
require_once __DIR__ . '/_delivery_control_ui.php';
$companyId=(int)COMPANY_ID;delivery_control_require_enabled($pdo,$companyId);$userId=dc_user_id();$id=(int)($_GET['id']??$_POST['id']??0);if($id<=0){http_response_code(400);die('Entrega inválida.');}
$msg='';$err='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
  try{dc_csrf_check((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
    if($action==='create_order'){$quantities=(array)($_POST['qty']??[]);$date=trim((string)($_POST['scheduled_date']??''));$notes=trim((string)($_POST['notes']??''));$doc=strtoupper(trim((string)($_POST['document_type']??'NFE')));if(!in_array($doc,['NFE','NFCE','SEM'],true))$doc='NFE';$oid=delivery_control_create_order($pdo,$companyId,$id,$quantities,$userId,$date!==''?$date:null,$notes,$doc==='SEM'?'':$doc);$msg='Ordem de Entrega #'.$oid.' gerada. O estoque dos itens selecionados foi baixado.';}
  }catch(Throwable $e){$err=$e->getMessage();}
}
$st=$pdo->prepare('SELECT s.*,p.numero_pedido,p.total FROM delivery_control_sales s LEFT JOIN pedidos p ON p.company_id=s.company_id AND p.id=s.pedido_id WHERE s.company_id=? AND s.id=? LIMIT 1');$st->execute([$companyId,$id]);$sale=$st->fetch(PDO::FETCH_ASSOC);if(!$sale){http_response_code(404);die('Entrega não encontrada.');}
$st=$pdo->prepare('SELECT * FROM delivery_control_sale_items WHERE company_id=? AND delivery_sale_id=? ORDER BY id');$st->execute([$companyId,$id]);$items=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$st=$pdo->prepare("SELECT o.*,COALESCE(SUM(oi.quantity),0) total_qty FROM delivery_control_orders o LEFT JOIN delivery_control_order_items oi ON oi.company_id=o.company_id AND oi.delivery_order_id=o.id WHERE o.company_id=? AND o.delivery_sale_id=? GROUP BY o.id ORDER BY o.id DESC");$st->execute([$companyId,$id]);$orders=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
dc_page_start('Entrega #'.$id,'controle_entregas');
?>
<div class="dc-head"><a class="dc-btn" href="delivery_control.php">← Voltar</a><h1>Entrega #<?=$id?></h1><span class="dc-badge <?=dc_status_class((string)$sale['status'])?>"><?=dc_e(dc_status_label((string)$sale['status']))?></span><div class="dc-spacer"></div><a class="dc-btn" href="pedidos.php?q=<?=(int)$sale['pedido_id']?>">Pedido #<?=(int)$sale['pedido_id']?></a></div>
<?php if($msg):?><div class="dc-alert"><?=dc_e($msg)?></div><?php endif;?><?php if($err):?><div class="dc-alert error"><?=dc_e($err)?></div><?php endif;?>
<div class="dc-card"><div class="dc-card-head">Cliente e entrega</div><div class="dc-card-body"><div class="dc-grid three"><div><strong><?=dc_e($sale['customer_name'])?></strong><div class="dc-muted"><?=dc_e($sale['customer_document'])?> · <?=dc_e($sale['customer_phone'])?></div></div><div><span class="dc-muted">Previsão</span><div><strong><?=dc_date($sale['expected_date'])?></strong><?=!empty($sale['expected_time'])?' · '.dc_e(substr((string)$sale['expected_time'],0,5)):''?></div></div><div class="dc-address"><span class="dc-muted">Endereço</span><div><strong><?=dc_e($sale['delivery_address'])?>, <?=dc_e($sale['delivery_number'])?></strong><br><?=dc_e($sale['delivery_district'])?> · <?=dc_e($sale['delivery_city'])?>/<?=dc_e($sale['delivery_state'])?></div></div></div></div></div>
<div class="dc-card"><div class="dc-card-head">Saldo da venda</div><div class="dc-card-body"><div class="dc-table-wrap"><table class="dc-table"><thead><tr><th>Produto</th><th class="num">Vendido</th><th class="num">Na hora</th><th class="num">Futuro</th><th class="num">Em O.E.</th><th class="num">Entregue</th><th class="num">Saldo para O.E.</th></tr></thead><tbody><?php foreach($items as $it):$avail=max(0,(float)$it['future_quantity']-(float)$it['ordered_quantity']);?><tr><td><strong><?=dc_e($it['product_name'])?></strong><div class="dc-muted"><?=dc_e($it['unit'])?></div></td><td class="num"><?=dc_qty($it['sold_quantity'])?></td><td class="num"><?=dc_qty($it['immediate_quantity'])?></td><td class="num"><?=dc_qty($it['future_quantity'])?></td><td class="num"><?=dc_qty($it['ordered_quantity'])?></td><td class="num"><?=dc_qty($it['delivered_quantity'])?></td><td class="num"><strong><?=dc_qty($avail)?></strong></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php if(!in_array((string)$sale['status'],['CONCLUIDA','CANCELADA'],true)):?><form method="post" class="dc-card"><input type="hidden" name="csrf" value="<?=dc_e(dc_csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="create_order"><div class="dc-card-head">Gerar Ordem de Entrega</div><div class="dc-card-body"><div class="dc-alert">Ao gerar a O.E., as quantidades informadas serão <strong>baixadas do estoque físico</strong> e retiradas da reserva. O documento fiscal, quando escolhido, irá para a fila fiscal isolada.</div><div class="dc-table-wrap"><table class="dc-table"><thead><tr><th>Produto</th><th class="num">Saldo disponível</th><th style="width:190px">Quantidade desta O.E.</th></tr></thead><tbody><?php foreach($items as $it):$avail=max(0,(float)$it['future_quantity']-(float)$it['ordered_quantity']);?><tr><td><?=dc_e($it['product_name'])?></td><td class="num"><?=dc_qty($avail)?> <?=dc_e($it['unit'])?></td><td><input style="width:150px" type="number" min="0" max="<?=$avail?>" step="0.0001" name="qty[<?=(int)$it['id']?>]" value="0" <?=$avail<=0?'disabled':''?>></td></tr><?php endforeach;?></tbody></table></div><div class="dc-grid three" style="margin-top:14px"><div class="dc-field"><label>Data programada</label><input type="date" name="scheduled_date" value="<?=dc_e((string)($sale['expected_date']??''))?>"></div><div class="dc-field"><label>Documento fiscal</label><select name="document_type"><option value="NFE">NF-e</option><option value="NFCE">NFC-e</option><option value="SEM">Não gerar fila fiscal</option></select></div><div class="dc-field"><label>Observações</label><input name="notes" placeholder="Observações da entrega"></div></div><div style="margin-top:14px"><button class="dc-btn primary" type="submit" onclick="return confirm('Gerar a Ordem de Entrega e baixar o estoque das quantidades informadas?')">Gerar Ordem de Entrega</button></div></div></form><?php endif;?>
<div class="dc-card"><div class="dc-card-head">Ordens desta entrega</div><div class="dc-card-body"><div class="dc-table-wrap"><table class="dc-table"><thead><tr><th>O.E.</th><th>Programação</th><th>Status</th><th class="num">Quantidade</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="5" class="dc-muted">Nenhuma Ordem de Entrega gerada.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><strong>#<?=str_pad((string)$o['order_number'],6,'0',STR_PAD_LEFT)?></strong></td><td><?=dc_date($o['scheduled_date'])?></td><td><span class="dc-badge <?=dc_status_class((string)$o['status'])?>"><?=dc_e(dc_status_label((string)$o['status']))?></span></td><td class="num"><?=dc_qty($o['total_qty'])?></td><td><a class="dc-btn sm" href="delivery_orders.php?q=<?=(int)$o['order_number']?>">Ver O.E.</a></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php dc_page_end(); ?>
